import json


def carregar_configuracao_segura(caminho_arquivo: str) -> dict:
    """Carrega configuração de um arquivo JSON, tratando erros previsíveis.

    Retorna um dict vazio se o arquivo não existir ou o conteúdo for
    JSON inválido, em vez de propagar a exceção.
    """
    try:
        with open(caminho_arquivo, "r", encoding="utf-8") as arquivo:
            return json.load(arquivo)
    except FileNotFoundError:
        return {}
    except json.JSONDecodeError:
        return {}

