import json

from carregador_config_seguro import carregar_configuracao_segura


def test_carrega_configuracao_valida(tmp_path):
    arquivo = tmp_path / "config.json"
    arquivo.write_text(json.dumps({"chave": "valor"}))

    assert carregar_configuracao_segura(str(arquivo)) == {"chave": "valor"}


def test_arquivo_inexistente_retorna_dict_vazio(tmp_path):
    caminho = tmp_path / "nao_existe.json"

    assert carregar_configuracao_segura(str(caminho)) == {}


def test_json_invalido_retorna_dict_vazio(tmp_path):
    arquivo = tmp_path / "invalido.json"
    arquivo.write_text("{invalido")

    assert carregar_configuracao_segura(str(arquivo)) == {}
